data.pageSchema:
{
  "renderer": "page",
  "initData": {
    "type": "1"
  },
  "body": [
    {
      "renderer": "service",
      "classname": "page_profile__service",
      "initApi": {
        "url": "/api/user",
        "method": "get",
        "cached": false,
        "params": {}
      },
      "body": [
        {
          "renderer": "grid",
          "span": "6,18",
          "body": [
            {
              "renderer": "card",
              "body": [
                {
                  "renderer": "avatar",
                  "src": "${avatar}",
                  "size": 80,
                  "shape": "circle",
                  "borderRadius": 0,
                  "color": "#606266",
                  "bgColor": "#ffffff",
                  "isComputedSrc": true,
                  "fit": "contain",
                  "subTitle": "${data.username}",
                  "description": "${data.namespace}"
                },
                {
                  "renderer": "action",
                  "text": "${data.email || '-'}",
                  "round": true,
                  "static": true,
                  "body": {},
                  "icon": "ChatLineSquare",
                  "classname": "margin-top-20"
                },
                {
                  "renderer": "divider"
                },
                {
                  "renderer": "form",
                  "controls": [
                    {
                      "renderer": "radio",
                      "name": "type",
                      "options": [
                        {
                          "text": "个人信息",
                          "value": "1",
                          "disabledOn": ""
                        },
                        {
                          "text": "密码",
                          "value": "2",
                          "disabledOn": ""
                        }
                      ],
                      "rules": [],
                      "target": "InfoForm"
                    }
                  ],
                  "inherit": {
                    "type": "all",
                    "value": []
                  }
                }
              ],
              "shadow": "never"
            },
            {
              "renderer": "card",
              "body": [
                {
                  "renderer": "form",
                  "controls": [
                    {
                      "renderer": "input",
                      "name": "namespace",
                      "label": "工作空间",
                      "placeholder": "请输入",
                      "type": "text",
                      "rules": [],
                      "hiddenOn": "data.type == 2",
                      "disabledOn": "1==1"
                    },
                    {
                      "renderer": "input",
                      "name": "password",
                      "label": "当前密码",
                      "placeholder": "请输入",
                      "type": "text",
                      "rules": [],
                      "hiddenOn": "data.type == 1",
                      "requiredOn": "1==1",
                      "showPassword": true
                    },
                    {
                      "renderer": "input",
                      "name": "password1",
                      "label": "新密码",
                      "placeholder": "请输入",
                      "type": "text",
                      "rules": [],
                      "hiddenOn": "data.type == 1",
                      "requiredOn": "1==1",
                      "showPassword": true
                    },
                    {
                      "renderer": "input",
                      "hiddenOn": "data.type == 1",
                      "name": "password2",
                      "label": "确认密码",
                      "placeholder": "请输入",
                      "type": "text",
                      "rules": [],
                      "requiredOn": "1==1",
                      "showPassword": true
                    },
                    {
                      "renderer": "input",
                      "name": "memory",
                      "label": "页面数量",
                      "placeholder": "请输入",
                      "type": "text",
                      "rules": [],
                      "hiddenOn": "data.type == 2",
                      "disabledOn": "1==1",
                      "append": {
                        "renderer": "html",
                        "html": "个"
                      }
                    },
                    {
                      "renderer": "input",
                      "name": "space",
                      "label": "剩余空间",
                      "placeholder": "请输入",
                      "type": "text",
                      "rules": [],
                      "hiddenOn": "data.type == 2",
                      "disabledOn": "1==1",
                      "append": {
                        "renderer": "html",
                        "html": "个"
                      }
                    },
                    {
                      "renderer": "datepicker",
                      "name": "until",
                      "label": "会员到期日",
                      "readonly": true,
                      "rules": [],
                      "type": "datetime",
                      "hiddenOn": "data.type == 2",
                      "disabledOn": "1==1"
                    },
                    {
                      "renderer": "action",
                      "text": "更新",
                      "visibleOn": "data.type == 2",
                      "popupType": "dialog",
                      "messageBoxExp": "1==1",
                      "popoverTitle": "确定修改吗？",
                      "actionType": "submit",
                      "body": {}
                    }
                  ],
                  "name": "InfoForm",
                  "inherit": {
                    "type": "all",
                    "value": []
                  },
                  "actionApi": {
                    "url": "/api/user/${id}/password",
                    "method": "put",
                    "params": {
                      "password": "${password}",
                      "password1": "${password1}",
                      "password2": "${password2}"
                    }
                  }
                }
              ],
              "header": [],
              "shadow": "never"
            }
          ],
          "gutter": 20
        }
      ]
    }
  ]
}
